    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]

    # Each ray crosses the center's adjacent 3 arm, then continues until it
    # encounters another 3 marker. Horizontal first; vertical overlays after.
    for r, c, color in centers:
        for step in (-1, 1):
            x, passed_arm = c + step, False
            while 0 <= x < w:
                if grid[r][x] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                else:
                    out[r][x] = color
                x += step
    for r, c, color in centers:
        for step in (-1, 1):
            y, passed_arm = r + step, False
            while 0 <= y < h:
                if grid[y][c] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                else:
                    out[y][c] = color
                y += step

    # Hollow 3-crosses are separators: the crossing's row and column are
    # left blank except for original markers and colored centers.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] ==
                    grid[r][c-1] == grid[r][c+1] == 3):
