    # a one-cell gap in the line, so the beam resumes after that gap.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + dr, c + dc
