                    continue
                rprev, cprev = r - dr, c - dc
                rnext, cnext = rr + dr, cc + dc
                if (0 <= rprev < h and 0 <= cprev < w and
                        grid[rprev][cprev] == 3 and
                        0 <= rnext < h and 0 <= cnext < w and
                        grid[rnext][cnext] == 3):
